package com.smartdairy.repository;
import com.smartdairy.entity.ReportSummary; import com.smartdairy.util.DBConnection; import java.sql.*;
public class ReportRepository {
 private double one(Connection c,String q)throws Exception{try(PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){return r.next()?r.getDouble(1):0;}}
 public ReportSummary summary()throws Exception{ReportSummary s=new ReportSummary();try(Connection c=DBConnection.getConnection()){s.setMilkToday(one(c,"SELECT COALESCE(SUM(quantity),0) FROM milk_collection WHERE collection_date=CURDATE()"));s.setMilkMonth(one(c,"SELECT COALESCE(SUM(quantity),0) FROM milk_collection WHERE MONTH(collection_date)=MONTH(CURDATE()) AND YEAR(collection_date)=YEAR(CURDATE())"));s.setSalesToday(one(c,"SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE DATE(order_date)=CURDATE()"));s.setSalesMonth(one(c,"SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE MONTH(order_date)=MONTH(CURDATE()) AND YEAR(order_date)=YEAR(CURDATE())"));s.setPaymentsReceived(one(c,"SELECT COALESCE(SUM(amount),0) FROM payments"));s.setPendingInvoices(one(c,"SELECT COALESCE(SUM(pending_amount),0) FROM invoices"));s.setExpensesToday(one(c,"SELECT COALESCE(SUM(amount),0) FROM expenses WHERE expense_date=CURDATE()"));s.setExpensesMonth(one(c,"SELECT COALESCE(SUM(amount),0) FROM expenses WHERE MONTH(expense_date)=MONTH(CURDATE()) AND YEAR(expense_date)=YEAR(CURDATE())"));}return s;}
}
